describe('Shapefile Service', () => {
  // Mock ColumnResolverService - returns COCOA_GENERIC columns (template ID 13)
  const mockColumnResolverService = {
    resolveColumns: jest.fn().mockResolvedValue({
      columns: [
        'Location Name',
        'Latitude',
        'Longitude',
        'Analysis Radius',
        'Analysis Area',
        'Commodity',
        'Country',
        'State',
        'Sub State',
        'gadmid',
        'Geometry',
        'location_id',
        'attributes',
        'ErrorDetails',
      ],
      source: 'commodity',
      resolvedFrom: 'commodity: GFWP_cocoa -> COCOA_GENERIC',
    }),
  } as unknown as ColumnResolverService;

  const afiGeometryService = new AfiGeometryService(mockColumnResolverService);

  const filters = {
    listId: 5642,
    listName: 'WRI',
    key: 'tmp-afivc',
    combinedColumnsSplitted: [],
    selectedLocationsList: [],
  };

  const dir = `/tmp/wri-${filters.key}`;
  const filePath = `${dir}/${filters.listName}.json`;

  beforeAll(() => {
    afiGeometryService.startEmail = jest.fn();
    afiGeometryService.errorEmail = jest.fn();
    afiGeometryService.finishedEmail = jest.fn();
    afiGeometryService.uploadFileToS3 = jest.fn();

    createDirectory(dir);
  });

  beforeEach(() => {
    afiGeometryService.start(filters);
  });

  afterEach(() => {
    fs.unlinkSync(filePath);
    fs.rmdirSync(dir);
  });

  test('When input data has 3 locations', async () => {
    afiGeometryService.process(geoData);

    await afiGeometryService.finish(filters);

    const csvData = fs.readFileSync(filePath, 'utf8');
    const lines = csvData.toString().split('\n');
    expect(lines).toStrictEqual(expectedResult);
    expect(afiGeometryService.uploadFileToS3).toHaveBeenCalled();
    expect(fs.existsSync(`/tmp/${filters.key}.zip`)).toBeTruthy();
  }, 70000);
});
